const st = msg.status || {};
const isConnected = st.text === "connected";
msg.payload = {
    connectionState: st.text || "unknown",
    healthStatus: isConnected ? "ONLINE" : "OFFLINE_OR_ERROR",
    connected: isConnected,
    timestamp: new Date().toISOString(),
    error: isConnected ? null : ("WebSocket disconnected or server unreachable at ws://localhost:8765/telemetry (Status: " + (st.text || "disconnected") + ")")
};
if (!isConnected) {
    node.warn("SparkShield WS connection degraded/disconnected: " + (st.text || "error"));
}
return msg;

msg.payload = {
    alertId: "ERR-INGEST-" + Date.now(),
    error: msg.error ? msg.error.message : "Unknown ingestion error",
    sourceNode: msg.error ? (msg.error.source ? msg.error.source.name : "unknown") : "unknown",
    timestamp: new Date().toISOString(),
    severity: "WARNING_INGESTION_ERROR"
};
return msg;

// Normal Grid Baseline Monitoring
const data = msg.payload;
const peakMv = data.peakMv || 0;
const confidence = data.confidence || 1.0;
const fftBins = data.fftBins || [];

// Compute low-frequency vs high-frequency energy ratio
let lowEnergy = 0;
let highEnergy = 0;
for (let i = 0; i < 4 && i < fftBins.length; i++) lowEnergy += fftBins[i];
for (let i = 4; i < 8 && i < fftBins.length; i++) highEnergy += fftBins[i];
const hfRatio = (highEnergy / (lowEnergy + highEnergy + 1e-5)).toFixed(4);

msg.payload = {
    status: "GRID_NORMAL",
    seqId: data.seqId,
    timestampMs: data.timestampMs,
    peakVoltageV: (peakMv / 1000.0).toFixed(3),
    opticalSensorV: ((data.opticalMv || 0) / 1000.0).toFixed(3),
    hfEnergyRatio: parseFloat(hfRatio),
    modelConfidence: confidence,
    inferenceLatencyUs: data.inferenceTimeUs
};

return msg;

const d = msg.payload;
msg.topic = "sparkshield/alerts/emp";
msg.payload = {
    alertId: "ALT-EMP-" + d.seqId,
    severity: "CRITICAL_LEVEL_1",
    tamperType: "EMP",
    confidence: d.confidence,
    message: "SIMULATION: High-voltage electromagnetic transient attack detected",
    sequenceId: d.seqId,
    timestamp: new Date().toISOString(),
    metrics: {
        peakMv: d.peakMv,
        riseTimeNs: d.riseTimeNs,
        decayTimeUs: d.decayTimeUs,
        opticalMv: d.opticalMv,
        inferenceTimeUs: d.inferenceTimeUs
    }
};
return msg;

